<?php $izmena=!empty($vozilo['ID']);$naslovStranice=$izmena?'Izmeni vozilo':'Dodaj vozilo';require __DIR__.'/../delovi/zaglavlje.php';$g=$vozilo['Godiste']??$vozilo['godiste']??date('Y');$gor=$vozilo['Gorivo']??$vozilo['gorivo']??'Dizel';$men=$vozilo['Menjac']??$vozilo['menjac']??'Manuelni';$sed=$vozilo['BrojSedista']??$vozilo['brojSedista']??5;$km=$vozilo['Kilometraza']??$vozilo['kilometraza']??0;$kat=$vozilo['Kategorija']??$vozilo['kategorija']??'Kompakt';$st=$vozilo['Status']??$vozilo['status']??'Slobodno';?><main class="stranica vozilo-forma-stranica"><div class="breadcrumb"><a href="index.php?stranica=vozila">Vozila</a><span>›</span><strong><?=$naslovStranice?></strong></div><section class="novo-hero vozilo-forma-hero"><div><span class="eyebrow">ŠIFARNIK VOZILA</span><h1><?=$naslovStranice?></h1><p>Unesite osnovne i tehničke podatke vozila.</p></div><div class="koraci-unosa"><span class="korak aktivan">1 <small>Identitet</small></span><span class="korak aktivan">2 <small>Tehnički podaci</small></span><span class="korak aktivan">3 <small>Cena i status</small></span></div></section><?php if($greska):?><div class="greska"><?=htmlspecialchars($greska)?></div><?php endif;?><form method="post"><div class="vozilo-forma-grid"><div class="vozilo-glavni-sadrzaj"><section class="panel forma-sekcija"><div class="forma-sekcija-zaglavlje"><span class="sekcija-ikona">🚘</span><div><span class="sekcija-broj">KORAK 01</span><h2>Osnovni podaci</h2></div></div><div class="forma-red"><div class="forma-polje"><label>Marka</label><input name="marka" required maxlength="50" value="<?=htmlspecialchars($vozilo['Marka']??$vozilo['marka']??'')?>"></div><div class="forma-polje"><label>Model</label><input name="model" required maxlength="50" value="<?=htmlspecialchars($vozilo['Model']??$vozilo['model']??'')?>"></div></div><div class="forma-polje"><label>Registracija</label><input name="registracija" required maxlength="20" value="<?=htmlspecialchars($vozilo['Registracija']??$vozilo['registracija']??'')?>"></div></section><section class="panel forma-sekcija"><div class="forma-sekcija-zaglavlje"><span class="sekcija-ikona">⚙️</span><div><span class="sekcija-broj">KORAK 02</span><h2>Tehnički podaci</h2></div></div><div class="forma-red"><div class="forma-polje"><label>Godište</label><input type="number" name="godiste" min="1950" max="<?=date('Y')+1?>" required value="<?=$g?>"></div><div class="forma-polje"><label>Kategorija</label><select name="kategorija"><?php foreach(['Ekonomična','Kompakt','Limuzina','SUV','Karavan','Kombi','Premium'] as $x):?><option <?=$kat===$x?'selected':''?>><?=$x?></option><?php endforeach;?></select></div></div><div class="forma-red"><div class="forma-polje"><label>Gorivo</label><select name="gorivo"><?php foreach(['Benzin','Dizel','Hibrid','Električni'] as $x):?><option <?=$gor===$x?'selected':''?>><?=$x?></option><?php endforeach;?></select></div><div class="forma-polje"><label>Menjač</label><select name="menjac"><?php foreach(['Manuelni','Automatski'] as $x):?><option <?=$men===$x?'selected':''?>><?=$x?></option><?php endforeach;?></select></div></div><div class="forma-red"><div class="forma-polje"><label>Broj sedišta</label><input type="number" name="brojSedista" min="1" max="60" required value="<?=$sed?>"></div><div class="forma-polje"><label>Kilometraža</label><input type="number" name="kilometraza" min="0" required value="<?=$km?>"></div></div></section><section class="panel forma-sekcija"><div class="forma-sekcija-zaglavlje"><span class="sekcija-ikona">💰</span><div><span class="sekcija-broj">KORAK 03</span><h2>Cena i raspoloživost</h2></div></div><div class="forma-red"><div class="forma-polje"><label>Cena po danu</label><input type="number" step="0.01" min="1" name="cenaPoDanu" required value="<?=htmlspecialchars((string)($vozilo['CenaPoDanu']??$vozilo['cenaPoDanu']??''))?>"></div><div class="forma-polje"><label>Status</label><select name="status"><?php foreach(['Slobodno','Iznajmljeno','Servis','Nedostupno'] as $x):?><option <?=$st===$x?'selected':''?>><?=$x?></option><?php endforeach;?></select></div></div></section></div><aside class="panel vozilo-rezime"><div class="rezime-zaglavlje"><span class="sekcija-broj">PREGLED</span><h2><?=$naslovStranice?></h2><p>Sačuvajte podatke kada proverite unos.</p></div><div class="rezime-red"><span>Kategorija</span><strong><?=$kat?></strong></div><div class="rezime-red"><span>Godište</span><strong><?=$g?></strong></div><div class="rezime-red"><span>Status</span><strong><?=$st?></strong></div><button class="dugme dugme-siroko" type="submit">Sačuvaj</button><a class="dugme dugme-sekundarno dugme-siroko" href="index.php?stranica=vozila">Otkaži</a></aside></div></form></main><?php require __DIR__.'/../delovi/podnozje.php';?>